<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Referral programmes · Crea-Biz EV</title><script src="/theme.js"></script><link rel="stylesheet" href="/platform.css"><link rel="stylesheet" href="/retail-partners.css"><script src="/money-input.js" defer></script><script src="/admin-referral-programmes.js" defer></script></head><body><main class="retail-wrap"><header><a href="/" data-t="home">Workspace</a><select id="language" aria-label="Language / اللغة"><option value="en">English</option><option value="ar">العربية</option></select><select id="theme-choice" aria-label="Theme / المظهر"><option value="system">System / النظام</option><option value="light">Light / فاتح</option><option value="dark">Dark / داكن</option></select></header><h1 data-t="title">Referral programmes</h1><p data-t="notice">Verified new members may opt in before their first charging payment. A qualifying paid invoice reserves two manual noncash rewards. No money, discount, points or delivery proof is created.</p><p id="status" role="status" aria-live="polite"></p><section id="workspace" hidden><button id="refresh" data-t="refresh">Refresh programmes</button><div id="programmes"></div><nav aria-label="Programme pagination"><button id="previous" data-t="previous">Previous</button><bdi id="page"></bdi><button id="next" data-t="next">Next</button></nav><details id="editor"><summary data-t="new">Publish immutable programme</summary><p data-t="termsNotice">Customers see both programme terms and the mandatory qualification rules. Stock and daily limits are shared with the canonical reward catalog. Revocation stops future qualifications; existing commitments remain subject to reviewed manual fulfillment.</p><button id="rewards-refresh" data-t="rewardsRefresh">Load reward choices</button><div id="rewards"></div><nav aria-label="Reward pagination"><button id="reward-previous" data-t="previous">Previous</button><bdi id="reward-page"></bdi><button id="reward-next" data-t="next">Next</button></nav><form id="programme-form"><label><span data-t="name">English name</span><input name="name" required maxlength="150" dir="auto"></label><label><span data-t="nameAr">Arabic name</span><input name="name_ar" required maxlength="150" dir="rtl"></label><label><span data-t="terms">English programme terms</span><textarea name="terms" required minlength="50" maxlength="10000" dir="auto"></textarea></label><label><span data-t="termsAr">Arabic programme terms</span><textarea name="terms_ar" required minlength="50" maxlength="10000" dir="rtl"></textarea></label><label><span data-t="currency">Qualifying invoice currency</span><select name="currency" id="currency" required></select></label><label><span data-t="minimum">Minimum qualifying invoice total</span><input name="minimum" inputmode="decimal" required maxlength="20" dir="ltr"></label><p><span data-t="referrerReward">Inviter reward</span>: <output id="referrer-choice"></output><input name="referrer_reward_id" type="hidden" required></p><p><span data-t="memberReward">New member reward</span>: <output id="member-choice"></output><input name="member_reward_id" type="hidden" required></p><label><span data-t="limit">Programme qualification limit</span><input name="claim_limit" type="number" min="1" max="1000000" required></label><label><span data-t="perReferrer">Qualifications per inviter</span><input name="per_referrer_limit" type="number" min="1" max="1000" required></label><label><span data-t="starts">Starts at (UTC)</span><input name="starts_at" type="datetime-local" required></label><label><span data-t="ends">Ends at (UTC)</span><input name="ends_at" type="datetime-local" required></label><button data-t="publish">Publish programme</button><button id="resolve" type="button" data-t="resolve">Find saved programme</button><button id="discard" type="button" data-t="discard">Clear draft</button></form></details></section></main></body></html>
